'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const html=fs.readFileSync('index.html','utf8');
const calendar=fs.readFileSync('sanabil-plan-calendar.js','utf8');
const host=fs.readFileSync('sanabil-live-v12.js','utf8');
const sw=fs.readFileSync('sanabil-offline-sw.js','utf8');
const fast=fs.readFileSync('supabase/migrations/20261025040000_calendar_fast_approval_queue.sql','utf8');
const optim=fs.readFileSync('supabase/migrations/20261025041000_calendar_reflow_set_based_and_horizon.sql','utf8');
const archive=fs.readFileSync('supabase/migrations/20261025042000_calendar_archived_plan_guard.sql','utf8');
new vm.Script(calendar);new vm.Script(host);
assert(html.includes('sanabil-build" content="20261025-v13.8.71"'));
assert(html.includes('/sanabil-plan-calendar.js?v=20261025-bulk-default1'));
assert(host.includes("window.__SanabilLiveBuild='20261025-v13.8.71'"));
assert(sw.includes('sanabil-shell-20261025-v50-bulk-default'));
assert(calendar.includes("client.rpc('apply_calendar_days_bulk_guarded'"),'authorized range classification RPC');
assert(calendar.includes('p_circle_ids:circlesBatch'),'bounded group of circles per transaction');
assert(!calendar.includes("client.rpc('apply_calendar_day_step_guarded'"),'old serial request loop removed');
assert(calendar.includes('for(let d=0;d<dates.length;d+=7)'),'bounded date chunks avoid long transactions');
assert(calendar.includes('get_calendar_reflow_status_guarded'),'separate queue status button');
assert(calendar.includes('لا يلزم إبقاء الصفحة مفتوحة'),'user is not asked to wait for reflow');
assert(calendar.includes('تم اعتماد'),'approval acknowledged only after reply');
assert(calendar.includes('if(error)throw Error(error.message'),'RPC errors are not masked as success');
assert(calendar.includes('sl-complex-group'),'complex/circle selection retained');
assert(calendar.includes('get_calendar_management_scope_guarded'),'server-scoped management retained');
assert(fast.includes('CREATE TABLE IF NOT EXISTS private.calendar_day_reflow_queue'),'durable queue exists');
assert(fast.includes('ON CONFLICT(circle_id,date_key,student_id) DO UPDATE'),'idempotent retries');
assert(fast.includes('private.can_access(circle_row.org_id,circle_row.complex_id,cid'),'server-side manager authorization');
assert(fast.includes("array['admin','manager','supervisor']"),'teachers cannot approve entire complex');
assert(fast.includes("REVOKE ALL ON FUNCTION public.approve_calendar_day_fast_guarded"),'anonymous callers cannot approve');
assert(fast.includes("REVOKE ALL ON FUNCTION private.process_calendar_day_reflow"),'worker cannot be called directly');
assert(fast.includes("private.active_user()"),'worker verifies initiator still active');
assert(fast.includes("cron.schedule('sanabil-calendar-fast-reflow'"),'background reconciliation is scheduled');
assert(fast.includes("EXCEPTION WHEN OTHERS THEN"),'one reflow failure does not poison other jobs');
assert(fast.includes("state='failed'"),'error state is visible');
assert(fast.includes("state='done'"),'successful work marked complete');
assert(fast.includes('left join public.plan_days md')&&fast.includes('private.effective_day_type(s.id,p_date)'), 'daily assignments hide holiday work before reflow');
assert(optim.includes('WITH eligible AS ('),'movement dates generated using one set-based mapping');
assert(optim.includes("IF EXISTS(SELECT 1 FROM _sanabil_shift_days WHERE new_date IS NULL)"),'insufficient future days refused');
assert(optim.includes('private.effective_day_type(v_plan.student_id,d::date)'),'future plan generation respects day classification');
assert(optim.includes('private.effective_day_type(v_mem.student_id,d.date_key)'),'recent reviews avoid excluded days');
assert(archive.includes("AND p.status=''active''"),'archived plans cannot block holiday approval');
const sandbox={window:{},document:{},console};
vm.runInNewContext(calendar,sandbox,{timeout:1200});
assert.equal(sandbox.window.SanabilPlanCalendar.officialFor('2026-10-25'),'إجازة إضافية للمدينة المنورة');
assert.equal(sandbox.window.SanabilPlanCalendar.officialFor('2028-11-24'),'');
console.log('PASS: immediate approval, protected scopes, queue, no serial browser work, plan regeneration and archived-plan safety');
